import GLib from 'gi://GLib';
import Gio from 'gi://Gio';
import St from 'gi://St';
import Clutter from 'gi://Clutter';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import {Extension} from 'resource:///org/gnome/shell/extensions/extension.js';

// Charger Cat: shows an animated 3D cat right next to the system battery icon in the
// GNOME top bar while the charger is plugged in. It reads the same UPower "display
// device" that GNOME's own battery icon uses.
//
// This file is the shared body of the extension. scripts/build-gnome-extension.mjs
// wraps it with the imports for GNOME 45+ (ES modules) and GNOME 42–44 (legacy).

const UPOWER_NAME = 'org.freedesktop.UPower';
const DISPLAY_DEVICE_PATH = '/org/freedesktop/UPower/devices/DisplayDevice';
const DeviceInterface = `
<node>
  <interface name="org.freedesktop.UPower.Device">
    <property name="State" type="u" access="read"/>
    <property name="Percentage" type="d" access="read"/>
    <property name="IsPresent" type="b" access="read"/>
  </interface>
</node>`;

// UPower device states.
const STATE_CHARGING = 1;
const STATE_FULLY_CHARGED = 4;
const STATE_PENDING_CHARGE = 5;

// Animation loops rendered from the 3D cat (see scripts/render-cat-frames.mjs).
const LOOPS = {
    run: {frames: 8, fps: 12}, // charging: gallop
    sit: {frames: 24, fps: 8}, // plugged in and full: sit and wag the tail
};
const COATS = ['ginger', 'smokey', 'snowball'];

function readCoat(dir) {
    try {
        const [ok, bytes] = GLib.file_get_contents(`${dir}/coat`);
        if (ok) {
            const coat = new TextDecoder().decode(bytes).trim();
            if (COATS.includes(coat))
                return coat;
        }
    } catch (e) {
        // No coat file: use the default cat.
    }
    return COATS[0];
}

class ChargerCat {
    constructor(dir) {
        this._mode = null;
        this._index = 0;
        this._animId = 0;
        this._attachId = 0;
        this._attachTries = 0;
        this._propsId = 0;
        this._destroyed = false;

        this.actor = new St.Widget({
            style_class: 'charger-cat',
            layout_manager: new Clutter.BinLayout(),
            y_align: Clutter.ActorAlign.CENTER,
            visible: false,
        });

        // One widget per frame; animating just switches which one is visible.
        const coat = readCoat(dir);
        this._frames = {};
        for (const [kind, loop] of Object.entries(LOOPS)) {
            this._frames[kind] = [];
            for (let i = 0; i < loop.frames; i++) {
                const frame = new St.Widget({
                    style_class: 'charger-cat-frame',
                    style: `background-image: url("file://${dir}/frames/${coat}/${kind}-${i}.png");`,
                    visible: false,
                });
                this.actor.add_child(frame);
                this._frames[kind].push(frame);
            }
        }

        this._attach();

        const DeviceProxy = Gio.DBusProxy.makeProxyWrapper(DeviceInterface);
        this._proxy = new DeviceProxy(Gio.DBus.system, UPOWER_NAME, DISPLAY_DEVICE_PATH, (proxy, error) => {
            if (this._destroyed)
                return;
            if (error) {
                console.error(`Charger Cat: cannot read the battery from UPower: ${error.message}`);
                return;
            }
            this._propsId = proxy.connect('g-properties-changed', () => this._sync());
            this._sync();
        });
    }

    // Put the cat immediately before the system battery icon in the top bar.
    _attach() {
        const area = Main.panel.statusArea;
        const quickSettings = area.quickSettings; // GNOME 43+
        const box = quickSettings?._indicators ?? area.aggregateMenu?._indicators;
        const battery = quickSettings ? quickSettings._system : area.aggregateMenu?._power;

        // GNOME creates the quick-settings indicators asynchronously at login.
        const ready = box && battery && battery.get_parent() === box;
        if (!ready && this._attachTries++ < 80) {
            this._attachId = GLib.timeout_add(GLib.PRIORITY_DEFAULT, 250, () => {
                this._attachId = 0;
                this._attach();
                return GLib.SOURCE_REMOVE;
            });
            return;
        }

        if (ready)
            box.insert_child_below(this.actor, battery);
        else if (box)
            box.add_child(this.actor);
        else
            Main.panel._rightBox.insert_child_at_index(this.actor, 0);
    }

    _sync() {
        const device = this._proxy;
        let mode = null;
        if (device.IsPresent) {
            if (device.State === STATE_CHARGING)
                mode = 'run';
            else if (device.State === STATE_FULLY_CHARGED || device.State === STATE_PENDING_CHARGE)
                mode = 'sit';
        }
        if (mode === this._mode)
            return;

        this._stopAnimation();
        if (this._mode)
            this._frames[this._mode][this._index].hide();

        this._mode = mode;
        this._index = 0;
        this.actor.visible = mode !== null;
        if (!mode)
            return;

        this._frames[mode][0].show();
        this._animId = GLib.timeout_add(GLib.PRIORITY_DEFAULT, Math.round(1000 / LOOPS[mode].fps), () => {
            const frames = this._frames[this._mode];
            frames[this._index].hide();
            this._index = (this._index + 1) % frames.length;
            frames[this._index].show();
            return GLib.SOURCE_CONTINUE;
        });
    }

    _stopAnimation() {
        if (this._animId) {
            GLib.source_remove(this._animId);
            this._animId = 0;
        }
    }

    // Used by tests: the current animation ('run', 'sit' or null).
    get mode() {
        return this._mode;
    }

    destroy() {
        this._destroyed = true;
        this._stopAnimation();
        if (this._attachId) {
            GLib.source_remove(this._attachId);
            this._attachId = 0;
        }
        if (this._propsId) {
            this._proxy.disconnect(this._propsId);
            this._propsId = 0;
        }
        this._proxy = null;
        this.actor.destroy();
        this.actor = null;
    }
}

export default class ChargerCatExtension extends Extension {
    enable() {
        this._cat = new ChargerCat(this.path);
    }

    disable() {
        this._cat?.destroy();
        this._cat = null;
    }

    // Used by tests.
    get cat() {
        return this._cat;
    }
}
